import {
  PATH_SEGMENT_TO_DOCUMENT_TYPE,
  titleFromPath,
} from '@linm-soft-org/linm-web-common-components';
import { openWorkspaceTab } from './openWorkspaceTab';
import type { InAppNavigateFn } from '../router/navigateInAppPath';

/** Mở route cross-MFE (vd. `/kt/pt/{id}`) qua shell workspace tab hoặc in-app navigate. */
export function openCrossMfePath(path: string, navigate: InAppNavigateFn): void {
  const normalized = path.startsWith('/') ? path : `/${path}`;
  const segments = normalized.split('/').filter(Boolean);
  const leafOrParent =
    segments.length >= 2 && /^[0-9a-f-]{36}$/i.test(segments[segments.length - 1])
      ? segments[segments.length - 2]
      : segments[segments.length - 1];
  const documentType =
    (leafOrParent && PATH_SEGMENT_TO_DOCUMENT_TYPE[leafOrParent]) || undefined;
  const title = titleFromPath(normalized);

  openWorkspaceTab(
    {
      path: normalized,
      title,
      documentType,
    },
    navigate,
  );
}
