import type { LinkedCashReceiptSummaryDto } from '../services/bh/models';

/** Receipt shell kind from IdCode prefix — parity BE SourceDocumentViewLinkBuilder. */
export type LinkedReceiptShellKind = 'phieu-thu' | 'bao-co';

export function linkedReceiptShellKind(code: string | null | undefined): LinkedReceiptShellKind {
  const c = (code ?? '').trim().toUpperCase();
  if (c.startsWith('BC')) return 'bao-co';
  return 'phieu-thu';
}

/** Fallback when BE omits viewUrl — route by mã CT. */
export function resolveLinkedReceiptViewUrl(
  receipt: Pick<LinkedCashReceiptSummaryDto, 'id' | 'code' | 'viewUrl'>,
): string {
  const fromBe = receipt.viewUrl?.trim();
  if (fromBe) return fromBe;
  if (linkedReceiptShellKind(receipt.code) === 'bao-co') {
    return `/kt/bao-co/${receipt.id}`;
  }
  return `/kt/pt/${receipt.id}`;
}

export function linkedReceiptOpenButtonLabel(code: string | null | undefined): string {
  return linkedReceiptShellKind(code) === 'bao-co' ? 'Mở báo có' : 'Mở phiếu thu';
}

export function linkedReceiptToolbarLabel(
  receipts: Pick<LinkedCashReceiptSummaryDto, 'code'>[],
): string {
  if (receipts.length === 0) return 'Xem phiếu thu';
  const kinds = new Set(receipts.map(r => linkedReceiptShellKind(r.code)));
  if (kinds.size === 1 && kinds.has('bao-co')) return 'Xem báo có';
  if (kinds.size === 1) return 'Xem phiếu thu';
  return 'Xem chứng từ thu';
}

export function linkedReceiptSlideoutTitle(
  receipts: Pick<LinkedCashReceiptSummaryDto, 'code'>[],
): string {
  if (receipts.length === 0) return 'Chứng từ thu liên kết';
  const kinds = new Set(receipts.map(r => linkedReceiptShellKind(r.code)));
  if (kinds.size === 1 && kinds.has('bao-co')) return 'Báo có liên kết';
  if (kinds.size === 1) return 'Phiếu thu liên kết';
  return 'Chứng từ thu liên kết';
}
